import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4
    numeric_pattern = re.compile(
        r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?"
    )

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    if records and records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    def repair_width(record):
        values = list(record)
        if len(values) > expected_width:
            values = values[: expected_width - 1] + [";".join(values[expected_width - 1 :])]
        elif len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        return values

    header_index = None
    fallback_index = None

    for index, record in enumerate(records):
        if len(record) == expected_width:
            if fallback_index is None:
                fallback_index = index
            nonempty = [value.strip() for value in record]
            if all(value and not numeric_pattern.fullmatch(value) for value in nonempty):
                header_index = index
                break

    if header_index is None:
        header_index = fallback_index

    if header_index is None:
        columns = [f"column_{index + 1}" for index in range(expected_width)]
        data_records = records
    else:
        columns = repair_width(records[header_index])
        data_records = records[header_index + 1 :]

    rows = [repair_width(record) for record in data_records]
    return {"columns": columns, "rows": rows}
